shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('tests/src/unit-udt.cpp')
s = p.read_text()
s = s.replace('#include <map>\n', '#include <cstdint>\n#include <limits>\n#include <map>\n', 1)
anchor = 'TEST_CASE("basic usage" * doctest::test_suite("udt"))\n'
assert s.count(anchor) == 1
regression = '''TEST_CASE("enum serialization preserves underlying signedness" * doctest::test_suite("udt"))
{
    SECTION("unsigned 64-bit enum")
    {
        enum class book_id : std::uint64_t {};
        const std::vector<std::pair<std::uint64_t, std::string>> values =
        {
            {0, "0"},
            {1, "1"},
            {(std::uint64_t(1) << 63) - 1, "9223372036854775807"},
            {std::uint64_t(1) << 63, "9223372036854775808"},
            {(std::numeric_limits<std::uint64_t>::max)() - 1, "18446744073709551614"},
            {(std::numeric_limits<std::uint64_t>::max)(), "18446744073709551615"}
        };

        for (const auto& value : values)
        {
            const auto id = static_cast<book_id>(value.first);
            const json j = id;
            CHECK(j.is_number_unsigned());
            CHECK(j == json(value.first));
            CHECK(to_string(j) == value.second);
            CHECK(j.get<book_id>() == id);
            CHECK(json::parse(j.dump()).get<book_id>() == id);
            if (value.first != 0)
            {
                CHECK(j > 0u);
            }

            json assigned = "previous value";
            assigned = id;
            CHECK(assigned.is_number_unsigned());
            CHECK(assigned == j);

            json converted;
            nlohmann::to_json(converted, id);
            CHECK(converted.is_number_unsigned());
            CHECK(converted == j);
        }
    }

    SECTION("unscoped unsigned enum")
    {
        enum unsigned_enum : std::uint32_t
        {
            max_value = (std::numeric_limits<std::uint32_t>::max)()
        };
        const json j = max_value;
        CHECK(j.is_number_unsigned());
        CHECK(j.dump() == "4294967295");
        CHECK(j.get<unsigned_enum>() == max_value);
    }

    SECTION("signed enum")
    {
        enum class signed_enum : std::int64_t {};
        const std::vector<std::int64_t> values =
        {
            (std::numeric_limits<std::int64_t>::min)(), -2, 0, 1,
            (std::numeric_limits<std::int64_t>::max)()
        };
        for (const auto value : values)
        {
            const auto e = static_cast<signed_enum>(value);
            const json j = e;
            CHECK(j.type() == json::value_t::number_integer);
            CHECK(j == json(value));
            CHECK(j.dump() == json(value).dump());
            CHECK(j.get<signed_enum>() == e);
        }
    }
}

'''
s = s.replace(anchor, regression + anchor)
p.write_text(s)
PY
cd /testbed/build && cmake .. > /tmp/json-enum-cmake.log && make test-udt_cpp11 > /tmp/json-enum-build.log && ./tests/test-udt_cpp11 --test-case='enum serialization preserves underlying signedness'

